            "harpy": "תחמושת משוטטת אוטונומית לגמרי (ללא הכוונת אדם) נגד מקורות קרינת מכ\"ם - ראש קרב נפץ כ-32 ק\"ג. פותחה לפני Harop וממשיכה לשמש לצידה בייעוד SEAD/דיכוי הגנה אווירית.",
            "heron mk2": "דגם משודרג של משפחת Heron - פרטי מטען מדויקים טרם פורסמו במלואם נכון לתחילת השירות; צפוי לשמר את יכולות ה-EO/IR, SAR ו-SIGINT האופייניות למשפחה.",
