            "dominator xp": "כטב\"ם MALE - פרטי מטען מדויקים אינם מפורסמים במלואם; פלטפורמת ISR בעיקרה, בדומה בייעודה למשפחות Heron/Hermes.",
            "spike firefly": "זוהי בעצמה תחמושת משוטטת זעירה - משקל כולל כ-2.2 ק\"ג, ראש קרב פיצוץ-רסס כ-350-420 גרם. חיישן EO/IR רב-ספקטרלי עם זיהוי קרבה. מיועדת ללחימה בשטח בנוי בטווח קצר (עד כ-1 ק\"מ), הוכחה מבצעית.",
            "heron tp": "מטען מרבי כ-1,000 ק\"ג ייעודי (עד 2,700 ק\"ג משקל המראה כולל). יכולת נשיאת מספר מטענים במקביל: SAR/GMTI, EO/IR, SIGINT. דווח על יכולת נשיאת תחמושת מדויקת בגרסאות מבצעיות. גובה טיסה קיצוני (עד כ-45,000 רגל).",
            "mq-4c triton": "מטען ייעודי: מכ\"ם פיקוח ימי רב-תפקודי AN/ZPY-3 (MFAS), חיישן EO/IR, מערכת ESM (איתור אלקטרוני), מקלט AIS. פלטפורמת ISR ימית טהורה - אינה נושאת חימוש.",
            "mq-9a reaper": "מטען מרבי כ-1,700 ק\"ג (כולל פנימי/חיצוני). חימוש טיפוסי: עד 4 טילי AGM-114 הלפייר ועד 2 פצצות מונחות GBU-12/GBU-38. חיישן MTS-B אלקטרו-אופטי/אינפרא-אדום ומכ\"ם SAR (Lynx). <b>דוגמה מאומתת:</b> פולין רכשה בפועל 800 טילי AGM-114R2 הלפייר במסגרת עסקת DSCA אמריקאית מפורסמת (2024) - זהו אחד המקרים הנדירים שבהם יש אישור פומבי מדויק לתצורת חימוש של מדינה ספציפית.",
            "mq-9b seaguardian": "גרסה ימית של משפחת MQ-9B. מטען: מכ\"ם פיקוח ימי, EO/IR, יכולת פריסת מצופי סונאר (sonobuoys), מקלט AIS - מיועדת בעיקר לפטרול ימי, עם אפשרות חימוש בתצורות מסוימות.",
