             "israelRelations": "פרופיל ייחוס - בעלת הברית המרכזית ובו-זמנית המתחרה הגדולה ביותר. **דריסת רגל חזקה מאוד:** Elbit Systems of America ו-IAI North America הן חברות בת אמריקאיות מלאות המייצרות ומספקות לצבא ארה\"ב ולגופים פדרליים - מודל מוכח לעקיפת מגבלות \"Buy American\". **הוכחה שגם פלטפורמות נמכרות:** Hero-120 של UVision נבחרה לחיל הנחתים ובאוקטובר 2025 זכתה בחוזה IDIQ של 982 מיליון דולר עם צבא היבשה (תוכנית LUS, דרך Mistral; עברה בדיקות קבלת סדרה ראשונה באוגוסט 2026), ו-THOR של אלביט (FUSE) נכנס לשירות ברמת הפלוגה (מאי 2026). **הזדמנות:** רכיבים, מטענים ו-C-UAV, וגם פלטפורמות קטנות דרך שותף אמריקאי - בזמן שהפנטגון קונה כטב\"מים קטנים בכמויות חסרות תקדים. **מגבלה:** חקיקת Buy American, תחרות מול ענקיות מקומיות (General Atomics, Northrop), ותלות במגבלות ITAR על רכיבים אמריקאיים בתוך מוצרים ישראליים. **עדכון 29.09.2026:** בחוזי ה-C-UAS \"Domestic Shield\" של צבא היבשה (10 חברות, תקרה כוללת 4.15 מיליארד דולר) נכללו RADA Technologies (ממקור ישראלי, כיום חלק מ-Leonardo DRS; תקרה 500 מיליון דולר) ו-SmartShooter הישראלית (תקרה 150 מיליון דולר). אלה תקרות IDIQ ולא התחייבות להוצאה.",
